class Solution {
    private int bestDiff = Integer.MAX_VALUE;

    private void dfs(int rem, int count, int minVal, int curMin, int curMax) {
        if (count == 1) {
            if (rem >= minVal) {
                int finalMin = Math.min(curMin, rem);
                int finalMax = Math.max(curMax, rem);
                bestDiff = Math.min(bestDiff, finalMax - finalMin);
            }
            return;
        }
        for (int d = minVal; (long) d * d <= rem; d++) {
            if (rem % d == 0) {
                dfs(rem / d, count - 1, d, Math.min(curMin, d), Math.max(curMax, d));
            }
        }
    }

    public int minFactorDifference(int n, int k) {
        bestDiff = Integer.MAX_VALUE;
        dfs(n, k, 1, Integer.MAX_VALUE, Integer.MIN_VALUE);
        return bestDiff == Integer.MAX_VALUE ? -1 : bestDiff;
    }
}

var minFactorDifference = function(n, k) {
    let bestDiff = Infinity;

    function dfs(rem, count, minVal, curMin, curMax) {
        if (count === 1) {
            if (rem >= minVal) {
                const finalMin = Math.min(curMin, rem);
                const finalMax = Math.max(curMax, rem);
                bestDiff = Math.min(bestDiff, finalMax - finalMin);
            }
            return;
        }
        for (let d = minVal; d * d <= rem; d++) {
            if (rem % d === 0) {
                dfs(Math.floor(rem / d), count - 1, d, Math.min(curMin, d), Math.max(curMax, d));
            }
        }
    }

    dfs(n, k, 1, Infinity, -Infinity);
    return bestDiff === Infinity ? -1 : bestDiff;
